(function(){
const general='Original teaching example; standard Japanese';
const sources={names:'https://www.irodori.jpf.go.jp/assets/data/starter/pdf/X_L03.pdf',repair:'https://www.irodori.jpf.go.jp/assets/data/starter/pdf/X_L02.pdf',register:'https://www.irodori.jpf.go.jp/assets/data/elementary01/pdf/Y_all.pdf',hobbies:'https://www.irodori.jpf.go.jp/assets/data/starter/pdf/X_L11.pdf',thanks:'https://www.irodori.jpf.go.jp/assets/data/elementary01/pdf/Y_L17.pdf'};
const p=([ja,kana,romaji,meaning])=>({ja,kana,romaji,meaning});
const d=(speaker,a)=>({speaker,...p(a)});
const w=(a,distractors,say)=>({kind:'word',...p(a),distractors,say,src:general,status:'general'});
const s=(a,tiles,distractors,say)=>({kind:'sentence',...p(a),tiles:tiles.map(([ja,romaji])=>({ja,romaji})),distractors:distractors.map(([ja,romaji])=>({ja,romaji})),transfer:false,say,src:general,status:'general'});
const g=(title,explanation,examples,q,options,answer,why)=>({kind:'grammar',title,explanation,examples:examples.map(p),quiz:{q,options,answer,why},say:explanation,src:general,status:'general'});
const c=(title,place,body,src,q,options,answer,why)=>({kind:'culture',title,place,body,src,quiz:{q,options,answer,why},say:body,status:'sourced'});
const q=(title,scene,prompt,options,answer)=>({kind:'scenario',title,scene,q:prompt,options:options.map(([text,why])=>({text,why})),answer,transfer:true,say:'Use the situation and relationship to choose a useful response.',src:general,status:'general'});
const lesson=(n,title,scene,mission,dialogue,items)=>({id:`u1l${n}`,title,scene,mission,dialogue,items:items.map((item,i)=>({id:`u1-${n}-${i+1}`,...item}))});
const unit={id:'u1',title:'First connections',blurb:'Meet your neighbors, find common ground, and keep a conversation going.',place:'A neighborhood in Tokyo',focus:'Greetings · introductions · conversation repair',lessons:[
lesson(1,'A hello that fits','It is morning at your apartment building. You meet Tanaka, a neighbor you do not know well.','Greet Tanaka politely in the morning. Then imagine meeting the same person in the evening and change your greeting.',[
d('You',['田中さん、おはようございます。','たなかさん、おはようございます。','Tanaka-san, ohayō gozaimasu.','Good morning, Tanaka.']),
d('Tanaka',['おはようございます。','おはようございます。','Ohayō gozaimasu.','Good morning.']),
d('You',['では、また。','では、また。','Dewa, mata.','See you again.'])],[
w(['おはようございます','おはようございます','ohayō gozaimasu','Good morning (polite)'],['Good evening','Good night','Thank you'],'A useful morning greeting for a neighbor or someone you have just met.'),
w(['こんにちは','こんにちは','konnichiwa','Hello / good afternoon'],['Good morning','See you tomorrow','Excuse me'],'The final は in this greeting is pronounced wa. Learn the greeting as a whole.'),
w(['こんばんは','こんばんは','konbanwa','Good evening'],['Good morning','Nice to meet you','I understand'],'Use this when greeting someone in the evening; it is not the bedtime farewell.'),
w(['では、また','では、また','dewa, mata','See you again'],['I am sorry','Welcome back','One more time'],'A friendly, neutral way to finish an encounter when you expect to meet again.'),
s(['田中さん、おはようございます。','たなかさん、おはようございます。','Tanaka-san, ohayō gozaimasu.','Good morning, Tanaka.'],[['田中','Tanaka'],['さん','san'],['おはようございます','ohayō gozaimasu']],[['こんばんは','konbanwa']],'You can address someone by name + san, then add the greeting.'),
g('Greetings are complete expressions','A greeting can stand alone. Do not add desu after konnichiwa. The longer ohayō gozaimasu is more polite than ohayō.',[['こんにちは。','こんにちは。','Konnichiwa.','Hello.'],['おはようございます。','おはようございます。','Ohayō gozaimasu.','Good morning.']],'Which is a complete ordinary greeting?',['こんにちはです (konnichiwa desu)','こんにちは (konnichiwa)','こんにちはます (konnichiwa masu)'],'こんにちは (konnichiwa)','Konnichiwa already works as a greeting without an extra ending.'),
c('Relationship before rigid rules','A first meeting','Polite and plain styles depend on the relationship and occasion. Start politely with a new neighbor; closer friends may choose shorter greetings. A shorter form is not automatically unfriendly.',sources.register,'You have just met your neighbor. What is a helpful starting point?',['Use a polite greeting and notice how the conversation develops','Assume every adult expects the same style forever','Copy the most casual greeting you have heard on television'],'Use a polite greeting and notice how the conversation develops','The situation gives you a reason to start politely, without turning formality into a permanent rule.'),
q('Evening at the entrance','At 7 pm, you meet Tanaka as both of you arrive home. You want to greet them, not say good night.','Which greeting fits this meeting?',[
['おはようございます (ohayō gozaimasu) — Good morning','This is the morning greeting in this everyday situation.'],['では、また (dewa, mata) — See you again','This closes an encounter rather than opening this one.'],['こんばんは (konbanwa) — Good evening','This greets your neighbor at an evening meeting.']],2)
]),
lesson(2,'Your name, your introduction','You join a small community class. The facilitator invites you to introduce yourself.','Say a greeting for a first meeting, your name with desu, and yoroshiku onegaishimasu. Use your own name instead of Alex.',[
d('Alex',['はじめまして。アレックスです。','はじめまして。アレックスです。','Hajimemashite. Arekkusu desu.','Nice to meet you. I am Alex.']),
d('Mori',['森です。よろしくお願いします。','もりです。よろしくおねがいします。','Mori desu. Yoroshiku onegaishimasu.','I am Mori. I look forward to getting to know you.']),
d('Alex',['こちらこそ、よろしくお願いします。','こちらこそ、よろしくおねがいします。','Kochira koso, yoroshiku onegaishimasu.','Likewise, I look forward to getting to know you.'])],[
w(['はじめまして','はじめまして','hajimemashite','Nice to meet you (first meeting)'],['Welcome home','See you again','Good night'],'Use this at a first introduction, not as your everyday greeting to an old friend.'),
w(['名前','なまえ','namae','Name'],['Country','Morning','Friend'],'Name labels often include this word. O-namae is a polite way to refer to another person’s name.'),
w(['アレックスです','アレックスです','Arekkusu desu','I am Alex'],['Alex is not here','My name is Mori','Where is Alex?'],'Replace Arekkusu with your name. Desu makes this a polite introduction.'),
w(['よろしくお願いします','よろしくおねがいします','yoroshiku onegaishimasu','I look forward to getting to know you (in an introduction)'],['Please say it more slowly','Good evening','I do not understand'],'This expression changes meaning with context. Here it warmly completes an introduction.'),
s(['私はアレックスです。','わたしはアレックスです。','Watashi wa Arekkusu desu.','I am Alex.'],[['私','watashi'],['は','wa'],['アレックス','Arekkusu'],['です','desu']],[['さん','san']],'Watashi wa sets the topic as “I.” The name comes before desu; do not attach san to your own name.'),
g('Name + desu','A name followed by desu is enough when the situation makes “I” clear. Watashi wa is optional in this introduction. The topic particle は is pronounced wa.',[['森です。','もりです。','Mori desu.','I am Mori.'],['私はアレックスです。','わたしはアレックスです。','Watashi wa Arekkusu desu.','I am Alex.']],'You are introducing yourself as Alex. Which fits?',['アレックスさんです (Arekkusu-san desu)','アレックスです (Arekkusu desu)','名前さん (namae-san)'],'アレックスです (Arekkusu desu)','Use your name without san when introducing yourself.'),
c('Let people choose their name','A community class','Family name + san is common when addressing Japanese acquaintances. Ask what name someone prefers rather than guessing. San is not gender-specific, and you do not attach it to your own name.',sources.names,'Mori introduces herself as Mori. How can you politely address her?',['Mori-san','Watashi-san','Assume you must use a given name'],'Mori-san','San follows the other person’s name. Follow their preference if they suggest another form.'),
q('A name tag and a new face','You are Alex. Mori introduces herself, then pauses so you can introduce yourself.','Which response supplies your name naturally?',[
['アレックスです。よろしくお願いします。 (Arekkusu desu. Yoroshiku onegaishimasu.) — I am Alex; pleased to meet you.','This gives your own name and completes the introduction.'],['森さんです。 (Mori-san desu.) — This is Mori.','That identifies Mori, not you.'],['もう一度お願いします。 (Mō ichido onegaishimasu.) — One more time, please.','A useful repair, but you understood and now need to introduce yourself.']],0)
]),
lesson(3,'Keep the conversation open','A classmate tells you which floor the classroom is on. You hear the beginning but miss the rest.','Politely ask for the number again. Then ask for slower speech without pretending you understood.',[
d('Mori',['教室は二階です。','きょうしつはにかいです。','Kyōshitsu wa nikai desu.','The classroom is on the second floor.']),
d('You',['すみません。もう一度お願いします。','すみません。もういちどおねがいします。','Sumimasen. Mō ichido onegaishimasu.','Sorry. One more time, please.']),
d('Mori',['二階です。','にかいです。','Nikai desu.','The second floor.']),
d('You',['わかりました。ありがとうございます。','わかりました。ありがとうございます。','Wakarimashita. Arigatō gozaimasu.','I understand. Thank you.'])],[
w(['すみません','すみません','sumimasen','Excuse me / I am sorry'],['I like it','Good night','It is expensive'],'Use this to politely get attention or introduce a request for repetition.'),
w(['もう一度','もういちど','mō ichido','One more time'],['Every day','A little earlier','The first floor'],'Mō extends the first vowel: ask for one more attempt, not a new topic.'),
w(['ゆっくり','ゆっくり','yukkuri','Slowly'],['Quickly','Yesterday','Nearby'],'The small っ creates a held consonant. This is useful when speech is too fast.'),
w(['わかりません','わかりません','wakarimasen','I do not understand'],['I understand','I will go','I like it'],'This states the problem plainly and politely. Follow it with a request that helps.'),
s(['すみません、もう一度お願いします。','すみません、もういちどおねがいします。','Sumimasen, mō ichido onegaishimasu.','Excuse me, one more time, please.'],[['すみません','sumimasen'],['もう一度','mō ichido'],['お願いします','onegaishimasu']],[['こんにちは','konnichiwa']],'First get attention, then name the repair you need: one more time.'),
g('A polite negative: wakarimasen','Wakarimasu means “I understand”; wakarimasen means “I do not understand.” Wakarimashita acknowledges that you have understood what was just explained.',[['わかりません。','わかりません。','Wakarimasen.','I do not understand.'],['ゆっくりお願いします。','ゆっくりおねがいします。','Yukkuri onegaishimasu.','Slowly, please.']],'You still do not understand. Which is accurate?',['わかりました (wakarimashita)','わかります (wakarimasu)','わかりません (wakarimasen)'],'わかりません (wakarimasen)','Masen is the polite negative ending in this expression.'),
c('Repair is participation','A conversation in class','Asking for repetition is a normal communication skill. Irodori introduces it at the start of its course. You can explain what would help instead of treating a smile or nod as proof of understanding.',sources.repair,'You missed the final part of an explanation. What supports mutual understanding?',['Ask for repetition','Nod and assume the details will become clear','Repeat your own name instead'],'Ask for repetition','A clear repair request gives the other person a useful next step.'),
q('Too fast to follow','The floor information is repeated, but the speaker is still speaking too quickly. You want the same information at a slower pace.','What will help most now?',[
['はじめまして (hajimemashite) — Nice to meet you','You have already met; this does not request a slower pace.'],['ゆっくりお願いします (yukkuri onegaishimasu) — Slowly, please','This identifies exactly what would help.'],['わかりました (wakarimashita) — I understand','This would signal understanding you do not yet have.']],1)
]),
lesson(4,'Something in common','During a break, you and Mori discuss what you enjoy. Your interests overlap, but they are not identical.','Say that you like music. Ask whether Mori likes films, and use watashi mo desu only if you truly share the preference.',[
d('You',['音楽が好きです。','おんがくがすきです。','Ongaku ga suki desu.','I like music.']),
d('Mori',['私もです。映画は好きですか？','わたしもです。えいがはすきですか？','Watashi mo desu. Eiga wa suki desu ka?','Me too. Do you like films?']),
d('You',['はい、好きです。','はい、すきです。','Hai, suki desu.','Yes, I do.'])],[
w(['音楽','おんがく','ongaku','Music'],['A station','A meal','A name'],'Use this broad word for music before learning specific genres.'),
w(['映画','えいが','eiga','Film / movie'],['A bookshop','A drink','A classroom'],'The kana spelling is えいが. Keep the first part long rather than dropping the i.'),
w(['好きです','すきです','suki desu','I like it'],['I do not understand','I am going home','It is tomorrow'],'Suki describes liking. Name the thing with ga when saying what you like.'),
w(['私もです','わたしもです','watashi mo desu','Me too'],['Only me','I do not like it','Who are you?'],'Use this after a statement that is also true for you.'),
s(['音楽が好きです。','おんがくがすきです。','Ongaku ga suki desu.','I like music.'],[['音楽','ongaku'],['が','ga'],['好き','suki'],['です','desu']],[['を','o']],'For this pattern, the liked thing comes before ga, then suki desu.'),
g('Ask about a preference','To ask a polite yes/no question, add ka. Eiga wa suki desu ka? makes films the topic: “As for films, do you like them?” A short answer can leave out the topic.',[['映画は好きですか？','えいがはすきですか？','Eiga wa suki desu ka?','Do you like films?'],['はい、好きです。','はい、すきです。','Hai, suki desu.','Yes, I do.']],'Which ending turns suki desu into a polite question?',['も (mo)','か (ka)','を (o)'],'か (ka)','Ka marks this as a question. Mo means “also”; o marks an object in other patterns.'),
c('Meet a person, not a category','A break between classes','A conversation about hobbies can include music, films, games, cooking, or anything the person enjoys. Ask about the individual instead of assuming that everyone shares a famous Japanese pastime.',sources.hobbies,'What is a useful way to start learning about a new classmate?',['Assume they like your favorite anime','Ask about their own interests','Treat one answer as the preference of the whole country'],'Ask about their own interests','The goal is to discover this person’s preferences, not confirm a stereotype.'),
q('A shared preference','Mori says “音楽が好きです” (Ongaku ga suki desu — I like music). You also like music.','Which short response shows the shared interest?',[
['私もです (watashi mo desu) — Me too','Mo expresses that the same statement is true for you.'],['わかりません (wakarimasen) — I do not understand','You understood the preference and want to share yours.'],['では、また (dewa, mata) — See you again','This closes the encounter instead of responding to the shared interest.']],0)
]),
lesson(5,'End on a kind note','After class, Mori helps you find a notebook you left behind. You thank her before heading home.','Thank Mori for the help and end the conversation politely. Say the full expression aloud, keeping the long ō in arigatō.',[
d('Mori',['ノート、ありました。','ノート、ありました。','Nōto, arimashita.','I found the notebook.']),
d('You',['ありがとうございます。助かります。','ありがとうございます。たすかります。','Arigatō gozaimasu. Tasukarimasu.','Thank you. That is a big help.']),
d('Mori',['いえいえ。','いえいえ。','Ie ie.','Not at all.']),
d('You',['では、失礼します。','では、しつれいします。','Dewa, shitsurei shimasu.','Well then, I will be going.'])],[
w(['ありがとうございます','ありがとうございます','arigatō gozaimasu','Thank you (polite)'],['Excuse me for leaving','One more time, please','Good evening'],'A versatile polite thank-you. Hold the ō sound in arigatō.'),
w(['助かります','たすかります','tasukarimasu','That helps me / I appreciate the help'],['I like films','I will return tomorrow','It is too large'],'This lets someone know their help makes a difference.'),
w(['ありがとうございました','ありがとうございました','arigatō gozaimashita','Thank you for what you have done'],['Please help me tomorrow','I do not understand yet','Welcome back'],'Often used to look back on completed help, service, or time together.'),
w(['失礼します','しつれいします','shitsurei shimasu','Excuse me (when leaving or entering, depending on context)'],['It is delicious','My name is Alex','I will say it again'],'Here it politely marks your departure. Its use depends on the scene.'),
s(['では、失礼します。','では、しつれいします。','Dewa, shitsurei shimasu.','Well then, I will be going.'],[['では','dewa'],['失礼','shitsurei'],['します','shimasu']],[['好き','suki']],'Dewa signals a transition; shitsurei shimasu is a polite departure expression here.'),
g('Thank-you in the present and after the event','Arigatō gozaimasu is a general polite thank-you. Arigatō gozaimashita often looks back on completed help. Both may fit some situations; the past form does not mean your gratitude has ended.',[['ありがとうございました。','ありがとうございました。','Arigatō gozaimashita.','Thank you for your help.'],['どうもありがとうございます。','どうもありがとうございます。','Dōmo arigatō gozaimasu.','Thank you very much.']],'What does gozaimashita add to a thank-you?',['A question about tomorrow','A look back at completed help or an occasion','A refusal of the help'],'A look back at completed help or an occasion','It refers back to what happened; it does not cancel present gratitude.'),
c('Gratitude can continue after the visit','After time together','A later thank-you message can acknowledge time spent together or help received. Irodori practices this after a home invitation. Keep your message specific to what the person did; a short sincere note is enough.',sources.thanks,'A classmate helped you today and you message later. What makes the message personal?',['Thank them for the specific help','Copy a long formal speech regardless of your relationship','Avoid mentioning the help because the day is over'],'Thank them for the specific help','The message connects your appreciation to the actual shared experience.'),
q('Leaving after the help','Mori has returned your notebook. You have thanked her and now need to leave.','Which expression clearly marks a polite departure?',[
['はじめまして (hajimemashite) — Nice to meet you','This begins a first introduction.'],['私もです (watashi mo desu) — Me too','There is no shared preference to agree with here.'],['では、失礼します (dewa, shitsurei shimasu) — Well then, I will be going','This fits the end of this polite encounter.']],2)
])],assessment:[
{id:'u1-check-1',...q('A new pottery group','It is your first time at an evening pottery class. Another learner gives their name too quickly for you to catch.','What should you do before trying to use their name?',[
['Say こんばんは (konbanwa — good evening), then もう一度お願いします (mō ichido onegaishimasu — one more time, please).','You greet them for the time of day and repair the missing information.'],['Say 私もです (watashi mo desu — me too) because they gave their name.','A name introduction is not a preference or statement to share this way.'],['Use a guessed name followed by san and move on.','San is polite, but guessing the name does not solve the misunderstanding.']],0)},
{id:'u1-check-2',...q('A conversation at the library','A new acquaintance says they like films. You genuinely share that interest. After chatting, they help you find the exit.','Which sequence reflects both moments?',[
['Say わかりません (wakarimasen — I do not understand), then introduce yourself again.','You understood and need to respond to the interest and help.'],['Say 私もです (watashi mo desu — me too), then ありがとうございます (arigatō gozaimasu — thank you) for the help.','The first phrase connects your interests; the second acknowledges the assistance.'],['Say こんばんは (konbanwa — good evening) in reply to each statement.','Repeating a greeting does not express the two different meanings.']],1)}]};
if(typeof KOMOREBI_UNITS!=='undefined')KOMOREBI_UNITS.push(unit);if(typeof module!=='undefined')module.exports=unit;
})();
